pub fn password_count_already_generated(
    charset: &[char],
    min_size: usize,
    starting_password: &str,
) -> usize {
    let base = charset.len();
    let mut count = 0;

    // Step 1: Count all passwords of shorter lengths
    for len in min_size..starting_password.len() {
        count += base.pow(len as u32);
